def findWords(board: list[list[str]], words: list[str]) -> list[str]:
    # Step 1: Build Trie
    trie = {}
    for word in words:
        curr = trie
        for c in word:
            if c not in curr: curr[c] = {}
            curr = curr[c]
        curr['$'] = word # Store full word at end node

    m, n = len(board), len(board[0])
    res = []

    def dfs(r, c, parent):
        char = board[r][c]
        curr_node = parent[char]

        # Check if word found
        word_match = curr_node.pop('$', None)
        if word_match:
            res.append(word_match)

        board[r][c] = '#' # Mark visited
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n and board[nr][nc] in curr_node:
                dfs(nr, nc, curr_node)
        board[r][c] = char # Backtrack

    for r in range(m):
        for c in range(n):
            if board[r][c] in trie:
                dfs(r, c, trie)

    return res

