class Solution {
public:
    std::vector<std::string> findWords(std::vector<std::vector<char>>& board, std::vector<std::string>& words) {
        TrieNode* root = new TrieNode();
        for (const auto& w : words) {
            TrieNode* curr = root;
            for (char c : w) {
                if (!curr->children.count(c)) curr->children[c] = new TrieNode();
                curr = curr->children[c];
            }
            curr->word = w;
        }
        std::vector<std::string> res;
        int m = board.size(), n = board[0].size();
        auto dfs = [&](auto& self, int r, int c, TrieNode* node) -> void {
            char temp = board[r][c];
            TrieNode* curr = node->children[temp];
            if (!curr->word.empty()) {
                res.push_back(curr->word);
                curr->word = ""; // Avoid duplicate
            }
            board[r][c] = '#';
            int dirs[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};
            for (auto& d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && board[nr][nc] != '#' && curr->children.count(board[nr][nc])) {
                    self(self, nr, nc, curr);
                }
            }
            board[r][c] = temp;
        };
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (root->children.count(board[r][c])) dfs(dfs, r, c, root);
            }
        }
        return res;
    }
};

