        char temp = board[r][c];
        TrieNode curr = node.children.get(temp);
        if (curr.word != null) {
            res.add(curr.word);
            curr.word = null;
        }
        board[r][c] = '#';
        int[][] dirs = {{-1,0},{1,0},{0,-1},{0,1}};
        for (int[] d : dirs) {
            int nr = r + d[0], nc = c + d[1];
            if (nr >= 0 && nr < board.length && nc >= 0 && nc < board[0].length && board[nr][nc] != '#' && curr.children.containsKey(board[nr][nc])) {
                dfs(board, nr, nc, curr, res);
            }
        }
        board[r][c] = temp;
    }
