class RadixTree:
    def __init__(self):
        self.root = RadixNode()

    def insert(self, word: str):
        curr = self.root
        while word:
            matched_child = None
            for edge, child in curr.children.items():
                # Find common prefix length
                common_len = 0
                while common_len < min(len(word), len(edge)) and word[common_len] == edge[common_len]:
                    common_len += 1
                if common_len > 0:
                    matched_child = (edge, child, common_len)
                    break

            if not matched_child:
                # No matching edge -> create new edge
                curr.children[word] = RadixNode(word)
                curr.children[word].is_end = True
                return
            else:
                edge, child, common_len = matched_child
                if common_len == len(edge):
                    curr = child
                    word = word[common_len:]
                else:
                    # Split edge
                    split_node = RadixNode(edge[:common_len])
                    del curr.children[edge]
                    curr.children[edge[:common_len]] = split_node

                    child.prefix = edge[common_len:]
                    split_node.children[child.prefix] = child

                    if common_len == len(word):
                        split_node.is_end = True
                    else:
                        rem_node = RadixNode(word[common_len:])
                        rem_node.is_end = True
                        split_node.children[word[common_len:]] = rem_node
                    return

